const rawText = $input.item.json.output;
const cleanText = rawText.replace(/```json/g, "").replace(/```/g, "").trim();
const parsed = JSON.parse(cleanText);

return [{ json: parsed }];

const axios = require('axios');
const FormData = require('form-data');

// Recupera il file binario dal nodo precedente
const binaryData = items[0].binary.data;
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');

// Prepara il form-data
const form = new FormData();
form.append('file', buffer, {
  filename: binaryData.fileName,
  contentType: binaryData.mimeType,
});

// Invia la richiesta a cv-extractor
const response = await axios.post('http://cv-preflight-extractor:8080/extract', form, {
  headers: {
    ...form.getHeaders(),
  },
});

// Restituisci la risposta JSON di cv-extractor
return [{ json: response.data }];

