const data = $input.first().json;
const preflight = $('Call CV preflight API').first().json;

const requiredChecks = [
  { name: 'candidate.full_name', fn: () => data.candidate?.full_name },
  { name: 'candidate.email_or_phone', fn: () => data.candidate?.email || data.candidate?.phone },
  { name: 'experience_or_education_or_skills', fn: () =>
      (data.experience?.length > 0) ||
      (data.education?.length > 0) ||
      (data.skills?.technical?.length > 0)
  }
];

const missing = requiredChecks
  .filter(c => !c.fn())
  .map(c => c.name);

const agencyDetected = data.agency_protected?.value === true;
const finalMissing = agencyDetected
  ? missing.filter(m => !['candidate.email_or_phone'].includes(m))
  : missing;

return [{
  json: {
    valid: finalMissing.length === 0,
    missing_fields: finalMissing,
    agency_protected: agencyDetected,
    risk_class: preflight.risk_class,
    readability_score: preflight.readability_score,
    file_id: preflight.file_id,
    data: data
  }
}];
